  const zh = lang === 'zh';
  const clinic = num(c.clinic, 385);
  const home = num(c.home, 510);
  return {
    kind: 'coverage',
    covered: true,
    currency: cur,
    deductible,
    rate,
    estimate,
    reimbursed,
    outOfPocket: estimate - reimbursed,
    points: [
      { ok: true, text: zh ? '意外从第一天起就保' : 'Accident covered from day 1' },
      {
        ok: true,
        text: zh
          ? `先付前 ${deductible} 瑞郎，之后报销 ${Math.round(rate * 100)}%`
          : `You pay the first ${cur} ${deductible}, then ${Math.round(rate * 100)}% is reimbursed`,
      },
      { ok: false, text: zh ? '上门费不保' : 'Home visit not covered', ref: 'AVB 1.2' },
      { ok: false, text: zh ? '之后的理疗不保' : 'Physiotherapy not covered', ref: 'AVB 1.2' },
      {
        ok: true,
        text: zh
          ? `估算自付：诊所约 ${cur} ${clinic}，上门约 ${cur} ${home}（含出租车 / 上门费）`
          : `Estimated cost to you: clinic about ${cur} ${clinic} vs home visit about ${cur} ${home}`,
      },
    ],
    simulated: true,
  };
}

export function createLivePhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const base = PHONE_AGENT_URL || '';
  const listeners = new Set();
  const timers = new Set();
  const state = { ended: false, audio: null };
  let started = false;

  const emit = (e) => {
    if (!state.ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true).
  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';

  async function say(line, useGradium) {
    if (useGradium && context.gradiumConsent === true && (await playGradium(base, line.original, voice, state))) return;
    if (state.ended) return;
    await speak(line.original, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
  }

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    let story;
    try {
      story = await fetchStory(base);
    } catch (err) {
      emit({ type: 'error', message: `Phone agent: ${err.message}` });
      finish();
      return;
    }
    await wait(1500);
    if (state.ended) return;
    emit({ type: 'status', state: 'connected' });

    const step = (story.steps || [])[STEP_INDEX[target] ?? 2] || { lines: [] };
    const lines = [
      { who: 'ai', original: FIRST_LINE.original, text: FIRST_LINE.text[lang] ?? FIRST_LINE.text.en, gradium: true },
      ...(step.lines || []).map((l) => ({
        who: /^pawse/i.test(l.speaker) ? 'ai' : 'callee',
        original: l.german,
        // The backend subtitles are English; the zh UI shows them as is rather than inventing a translation.
        text: l.subtitle,
      })),
    ];
    for (const line of lines) {
      await wait(450);
      if (state.ended) return;
      emit({ type: 'speaking', who: line.who });
      const ev = { type: 'line', who: line.who, original: line.original, text: line.text };
      if (line.who === 'callee') ev.simulated = true;
      emit(ev);
      await say(line, line.gradium);
      if (state.ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
    await wait(500);
    if (state.ended) return;
    emit({ type: 'result', ...(target === 'insurance' ? buildInsuranceResult(story, lang) : buildVetResult(story, lang, context)) });
    finish();
  }

  function finish() {
    if (state.ended) return;
    emit({ type: 'status', state: 'ended' });
    state.ended = true;
    timers.forEach(clearTimeout);
    timers.clear();
    if (state.audio) {
      try { state.audio.pause(); } catch { /* ignore */ }
      state.audio = null;
    }
    stopSpeech();
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run().catch((err) => {
        emit({ type: 'error', message: String(err && err.message ? err.message : err) });
        finish();
      });
    },
    hangup: finish,
  };
}
// Plain-Node check of the live phone agent with stubbed fetch (no browser, no speech, no Audio).
import assert from 'node:assert/strict';
import { validateResult } from '../src/contracts.js';

const story = {
  costs: { currency: 'CHF', treatment: 600, remaining_deductible: 300, reimbursement_rate: 0.8, reimbursed: 240, clinic: 385, home: 510 },
  calendar: { appointment: '16:30' },
  steps: [{ lines: [] }, { lines: [] },
    { lines: [
      { speaker: 'Pawse', german: 'Meine Katze Mimi hinkt.', subtitle: 'My cat limps.' },
      { speaker: 'Vet · simulated', german: 'Termin um 16:30.', subtitle: 'Appointment at 16:30.' }] },
    { lines: [
      { speaker: 'Pawse', german: 'Ist das gedeckt?', subtitle: 'Is it covered?' },
      { speaker: 'Insurer · simulated', german: 'Ja, 80 Prozent.', subtitle: 'Yes, 80%.' }] }],
};
const calls = [];
globalThis.fetch = async (url, opts) => {
  calls.push(String(url));
  if (String(url).endsWith('/api/v1/demo/mimi')) return { ok: true, status: 200, json: async () => story };
  return { ok: false, status: 503, blob: async () => null };
};

const { createLivePhoneCall } = await import('../src/agents/livePhoneAgent.js');

async function runCall(target, context = {}) {
  const call = createLivePhoneCall({ target, lang: 'en', context, speed: 1000 });
  const ev = [];
  call.on((e) => ev.push(e));
  call.start();
  for (let i = 0; i < 400 && !ev.some((e) => e.type === 'status' && e.state === 'ended'); i++) await new Promise((r) => setTimeout(r, 10));
  return { call, ev };
}

for (const [target, ctx] of [['vet', { clinic: { name: 'Praxis X' } }], ['insurance', { gradiumConsent: true }]]) {
  const { call, ev } = await runCall(target, ctx);
  const states = ev.filter((e) => e.type === 'status').map((e) => e.state);
  assert.deepEqual(states, ['dialing', 'connected', 'ended'], `${target} status order`);
  const lines = ev.filter((e) => e.type === 'line');
  assert.ok(lines[0].who === 'ai' && lines[0].original.includes('KI-Assistent'), 'first line discloses KI-Assistent');
  assert.ok(lines.filter((l) => l.who === 'callee').length >= 1);
  assert.ok(lines.filter((l) => l.who === 'callee').every((l) => l.simulated === true), 'callee lines simulated');
  const r = ev.find((e) => e.type === 'result');
  assert.ok(r && r.simulated === true, 'result simulated');
  assert.deepEqual(validateResult(target, r), [], `${target} result valid`);
  if (target === 'vet') assert.equal(r.place, 'Praxis X');
  else { assert.equal(r.reimbursed, 240); assert.equal(r.outOfPocket, 360); assert.ok(r.points.some((p) => !p.ok)); }
  const n = ev.length;
  call.hangup(); call.hangup();
  assert.equal(ev.length, n, 'hangup after end is a no-op');
  assert.ok(!ev.some((e) => e.type === 'error'), 'no error event');
}

// hangup mid-call ends exactly once
{
  const call = createLivePhoneCall({ target: 'vet', lang: 'en', speed: 1 });
  const ev = [];
  call.on((e) => ev.push(e));
  call.start();
  await new Promise((r) => setTimeout(r, 20));
  call.hangup(); call.hangup();
  await new Promise((r) => setTimeout(r, 100));
  assert.equal(ev.filter((e) => e.type === 'status' && e.state === 'ended').length, 1);
  assert.ok(!ev.some((e) => e.type === 'result'));
}
