    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, lang]);

  useEffect(() => {
    if (status !== 'connected') return undefined;
    const id = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, [status]);

  useEffect(() => {
    const el = listRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [lines, result]);

  const hangup = () => {
    callRef.current && callRef.current.hangup();
    onDone(resultRef.current);
  };

  const toggleSound = () => {
    const next = !soundOn;
    setSoundOn(next);
    setSpeechMuted(!next);
  };

  const statusText = status === 'dialing' ? t.dialing : status === 'connected' ? `${t.inCall} · ${fmt(secs)}` : t.callEnded;

  return (
    <main className="pc">
      <header className="pc-head">
        <div className={`pc-callee ${speaking === 'callee' ? 'talking' : ''} ${status === 'dialing' ? 'ringing' : ''}`}>
          <span aria-hidden="true">{callee.icon}</span>
        </div>
        <h1>{callee.name}</h1>
        <p className="muted">
          {callee.role} · {statusText}
        </p>
        <span className="pill">{t.liveTranslate}</span>
      </header>

      <div className="pc-pawse">
        <Avatar size={44} speaking={speaking === 'ai'} />
        <span>{t.aiNote}</span>
      </div>

      <section className="pc-lines" ref={listRef} aria-live="polite">
        {lines.map((l, i) => (
          <div key={i} className={`line line-${l.who}`}>
            <span className="line-who">{l.who === 'ai' ? t.pawse : callee.name}</span>
            {l.simulated && <span className="sim-badge">{t.simulated}</span>}
            <p className="line-original" lang="de">{l.original}</p>
            <p className="line-text">{l.text}</p>
          </div>
        ))}
        {result && <ResultCard t={t} target={target} result={result} />}
        {error && <p className="pc-error">{error}</p>}
      </section>

      <footer className="pc-foot">
        {result || status === 'ended' ? (
          <button type="button" className="btn primary wide" onClick={() => onDone(resultRef.current)}>
            {t.backToPawse}
          </button>
        ) : (
          <div className="pc-controls">
            <button type="button" className="pc-ctl" onClick={toggleSound} aria-pressed={!soundOn} aria-label={t.sound}>
              <Icon name={soundOn ? 'volume' : 'volumeOff'} />
            </button>
            <button type="button" className="pc-ctl hang" onClick={hangup} aria-label={t.hangup}>
              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
            </button>
            <span className="pc-ctl-spacer" />
          </div>
        )}
      </footer>
    </main>
  );
}
import { useEffect, useState } from 'react';
import Home from './pages/Home.jsx';
import VoiceCall from './pages/VoiceCall.jsx';
import ClinicList from './pages/ClinicList.jsx';
import PhoneCall from './pages/PhoneCall.jsx';
import Plan from './pages/Plan.jsx';
import { strings, detectLang, saveLang } from './i18n.js';
import { primeSpeech } from './agents/speech.js';
import { buildSummary } from './utils/summary.js';

// home → voice call with Pawse → advice
//   → "call the vet": clinic list → Pawse calls the chosen clinic
//   → "call the insurer": Pawse calls the insurer
//   → plan (summary)
export default function App() {
  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
  const [lang, setLangState] = useState(detectLang);
  const [triage, setTriage] = useState(null);
  const [vet, setVet] = useState(null);
  const [insurance, setInsurance] = useState(null);
  const [clinic, setClinic] = useState(null);
  const [target, setTarget] = useState(null);

  const t = strings[lang];

  const setLang = (l) => {
    setLangState(l);
    saveLang(l);
  };

  useEffect(() => {
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
  }, [lang]);

  const startCall = () => {
    primeSpeech(); // unlock speech on iOS while we are inside the tap
    setTriage(null);
    setVet(null);
    setInsurance(null);
    setClinic(null);
    setView('voice');
  };

  const call = (to) => {
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    setTarget(to);
    setView('phone');
  };

  const pickClinic = (c) => {
    primeSpeech();
    setClinic(c);
    setTarget('vet');
    setView('phone');
  };

  const callDone = (result) => {
    if (result && target === 'vet') setVet(result);
    if (result && target === 'insurance') setInsurance(result);
    setView(triage ? 'plan' : 'home');
  };

  if (view === 'voice') {
    return (
      <VoiceCall
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onTriage={setTriage}
        onCall={call}
        onEnd={() => setView(triage ? 'plan' : 'home')}
      />
    );
  }
  if (view === 'clinics') {
    // Going back from the list never restarts the voice call: show the plan instead.
    return <ClinicList t={t} lang={lang} triage={triage} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
  }
  if (view === 'phone') {
    return (
      <PhoneCall
        key={`${target}-${clinic ? clinic.id : ''}`}
        t={t}
        lang={lang}
        target={target}
        clinic={target === 'vet' ? clinic : null}
        context={{
          summary: buildSummary({ lang, triage, vet, insurance }),
          clinic: target === 'vet' ? clinic : undefined,
          estimate: vet ? vet.estimate : undefined,
        }}
        onDone={callDone}
      />
    );
  }
  if (view === 'plan' && triage) {
    return (
      <Plan
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onCall={call}
        onRestart={() => setView('home')}
      />
    );
  }
  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} />;

